/*
 * Natural Functional Substances Laboratory — self-contained image loader.
 * Includes 79 optimized images. No network request for images.bundle.bin.
 * Keep the existing HTML and CSS unchanged. Upload this file in the project root.
 */
(() => {
  'use strict';
  const images = {"2022학회.png":"","2025연말1.png":"","2025연말2.png":"","2025학회.png":"","2025학회2.png":"","2026워크숍 참가.png":"","23년도대학원.png":"","6가지assay.png":"","AI플로우.png":"","GC-MS활용1.png":"","GC-MS활용2.png":"","GC.png":"","GC사진.png":"","GC워크플로우.png":"","JSH.png":"","lab-logo.png":"","lab.png":"","lab1.png":"","lab2.png":"","lab3.png":"","lab4.png":"","lab5.png":"","lab6.png":"","lab7.png":"","lab8.png":"","LYM.png":"","MS흐름.png":"","NMR데이터.png":"","NMR데이터2.png":"","photo1.png":"","photo2.png":"","photo3.png":"","photo4.png":"","photo5.png":"","plant-metabolite-workflow.png":"","popup-banner.png":"","popup-banner2.png":"","research-analysis-data.png":"","research-analysis.png":"","research-bioactivity-data.png":"","research-bioactivity.png":"","research-introduce.png":"","research-separation.png":"","sogogi.png":"","ssdinner.png":"","SYY.png":"","고은정수상.png":"","교수님서계심.png":"","교수님수상.png":"","교수님찐수상.png":"","교수님총장옆.png":"","깻잎GC-MS활용.png":"","나무대사체.png":"","내부1.png":"","내부2.png":"","내부3.png":"","내부4.png":"","내부5.png":"","내부6.png":"","도킹도킹.png":"","매스플로우.png":"","박동현수상.png":"","박동현수상2.png":"","볼링.png":"","생육시기별GC.png":"","솥뚜껑.png":"","솥뚜껑외부.png":"","신형HPLC교육.png":"","실험실소개.png":"","애질런트교육.png":"","연구목적.png":"","연구목적2.png":"","워크플로우.png":"","이소플라본에스트로겐.png":"","전세현수상.png":"","전세현우수논문상수상.png":"","전세현우수연구상수상.png":"","천연물영어.png":"","후드쪽.png":""};

  function installImages() {
    const urls = new Map();
    const targets = document.querySelectorAll('img[data-bundled-src]');
    for (const img of targets) {
      const filename = img.getAttribute('data-bundled-src');
      const encoded = images[filename];
      if (!encoded) {
        console.warn('Missing bundled image:', filename);
        continue;
      }
      try {
        let objectUrl = urls.get(filename);
        if (!objectUrl) {
          const binary = atob(encoded);
          const bytes = new Uint8Array(binary.length);
          for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
          objectUrl = URL.createObjectURL(new Blob([bytes], { type: 'image/webp' }));
          urls.set(filename, objectUrl);
        }
        img.src = objectUrl;
        img.removeAttribute('data-bundled-src');
      } catch (error) {
        console.error('Cannot display:', filename, error);
      }
    }
    window.addEventListener('pagehide', () => {
      for (const url of urls.values()) URL.revokeObjectURL(url);
    }, { once: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', installImages, { once: true });
  } else {
    installImages();
  }
})();
